-- =====================================================================
-- ESPACE ADMIN (étape 1) : comptes admin + actualités dans la base
-- Date : 2026-11-17
--
-- À importer UNE FOIS dans phpMyAdmin :
--   1) choisir la base du site à gauche (local : csc_db / serveur : la base cPanel)
--   2) onglet "Importer" > choisir ce fichier > "Exécuter"
-- Ce fichier crée 3 tables et y copie les 16 actualités de Data/actualites.php.
-- Il peut être ré-importé sans danger : les actualités déjà présentes
-- (même id) ne sont pas écrasées.
-- =====================================================================

SET NAMES utf8mb4;

-- Comptes de l'espace admin (le premier compte se crée sur admin/setup.php)
CREATE TABLE IF NOT EXISTS `admins` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(50) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_login` DATETIME NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tentatives de connexion ratées (blocage après 5 essais en 15 minutes)
CREATE TABLE IF NOT EXISTS `admin_login_attempts` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `ip` VARCHAR(45) NOT NULL,
  `attempted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ip_time` (`ip`, `attempted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Actualités (position la plus haute = affichée en premier)
CREATE TABLE IF NOT EXISTS `actualites` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `position` INT NOT NULL DEFAULT 0,
  `date_pub` DATE NULL DEFAULT NULL,
  `image` VARCHAR(255) NOT NULL DEFAULT '',
  `label_fr` VARCHAR(120) NOT NULL DEFAULT '',
  `label_ar` VARCHAR(120) NOT NULL DEFAULT '',
  `titre_fr` VARCHAR(255) NOT NULL DEFAULT '',
  `titre_ar` VARCHAR(255) NOT NULL DEFAULT '',
  `resume_fr` TEXT NOT NULL,
  `resume_ar` TEXT NOT NULL,
  `contenu_fr` MEDIUMTEXT NOT NULL,
  `contenu_ar` MEDIUMTEXT NOT NULL,
  `tags` VARCHAR(500) NOT NULL DEFAULT '',
  `galerie` TEXT NOT NULL,
  `bouton_lien` VARCHAR(500) NOT NULL DEFAULT '',
  `bouton_fr` VARCHAR(120) NOT NULL DEFAULT '',
  `bouton_ar` VARCHAR(120) NOT NULL DEFAULT '',
  `publie` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_publie_position` (`publie`, `position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Les actualités actuelles du site (copiées de Data/actualites.php)
INSERT IGNORE INTO `actualites`
  (`id`, `position`, `date_pub`, `image`, `label_fr`, `label_ar`, `titre_fr`, `titre_ar`, `resume_fr`, `resume_ar`, `contenu_fr`, `contenu_ar`, `tags`, `galerie`, `bouton_lien`, `bouton_fr`, `bouton_ar`, `publie`)
VALUES
(25, 16, '2026-11-17', 'images/Actualite/next-csc-esba.jpg', '📅 Next match', '📅 المباراة القادمة', 'Next match : CSC – ES Ben Aknoun', 'المباراة القادمة: شباب قسنطينة – نجم بن عكنون', 'Dans le silence du tunnel, la concentration naît avant la tempête. 10e journée : CSC – ESBA, mercredi 18 novembre 2026 à 17h45 au stade Chahid Hamlaoui.', 'في صمت النفق.. يولد التركيز قبل العاصفة. الجولة 10: شباب قسنطينة – نجم بن عكنون، الأربعاء 18 نوفمبر 2026 على الساعة 17:45 بملعب الشهيد حملاوي.', 'Dans le silence du tunnel, la concentration naît avant la tempête.\n⚔️ Next match : CSC – ESBA (Ligue 1 Mobilis, 10e journée)\n⏱️ Mercredi 18 novembre 2026 à 17h45\n🏟️ Stade Chahid Hamlaoui, Constantine', 'في صمت النفق.. يولد التركيز قبل العاصفة.\n⚔️ المباراة القادمة: شباب قسنطينة – نجم بن عكنون (الجولة 10 من الرابطة المحترفة الأولى موبيليس)\n⏱️ الأربعاء 18 نوفمبر 2026 على الساعة 17:45\n🏟️ ملعب الشهيد حملاوي، قسنطينة', '#TheDean1898 #CSCESBA #DimaCsc', '', '', '', '', 1),
(24, 15, '2026-11-13', 'images/Actualite/amical-csc-osba.jpg', '⚽ Match amical', '⚽ مباراة ودية', 'Friendly game : CSC – Olympique Sidi Ben Adda', 'مباراة ودية: النادي الرياضي القسنطيني – أولمبيك سيدي بن عدة', 'Match amical face à l\'Olympique Sidi Ben Adda, vendredi 13 novembre 2026 à 17h00 au Centre technique régional de Tlemcen.', 'مباراة ودية ضد أولمبيك سيدي بن عدة، يوم 13 نوفمبر 2026 على الساعة 17:00 بالمركز التقني الجهوي الرياضي تلمسان.', '⛳️ Match amical\n⚽️ CS Constantine 🆚 Olympique Sidi Ben Adda\n⏱️ Vendredi 13 novembre 2026, coup d\'envoi à 17h00\n🏟 Centre technique régional sportif de Tlemcen', '⛳️ مباراة ودية\n⚽️ النادي الرياضي القسنطيني 🆚 أولمبيك سيدي بن عدة\n⏱️ 13 نوفمبر 2026 على الساعة 17:00\n🏟 المركز التقني الجهوي الرياضي تلمسان', '#TheDean1898 #FriendlyGame', '', '', '', '', 1),
(23, 14, NULL, 'images/Actualite/ft-jss-csc-1-0.jpg', '⚽ Résultat', '⚽ نتيجة', 'Full time : JS Saoura 1 – 0 CSC', 'نهاية المباراة: شبيبة الساورة 1 – 0 شباب قسنطينة', 'Courte défaite du Doyen face à la JS Saoura (1-0) en Ligue 1 Mobilis.', 'هزيمة بأقل نتيجة للعميد أمام شبيبة الساورة (1-0) في الرابطة المحترفة الأولى موبيليس.', '', '', '#TheDean1898 #JSSCSC', '', '', '', '', 1),
(22, 13, NULL, 'images/Actualite/starting-xi-jss-csc.jpg', '📋 Composition', '📋 التشكيلة', 'Starting XI : JS Saoura – CSC', 'التشكيلة الأساسية: شبيبة الساورة – شباب قسنطينة', 'Le onze de départ du Doyen face à la JS Saoura.', 'التشكيلة الأساسية للعميد أمام شبيبة الساورة.', 'Le onze de départ du CS Constantine face à la JS Saoura :\nMelala (GB) – Meddahi (C), Chikhi, Zeghad, Atibu, Bizimana, Berkane, Bakir, Lahmeri, L\'Ghoul, Evra.\nRemplaçants : Necir, Benmoussa, Belgourai, Ayoune, Rogers, Chaban, Djaouchi, Chekal, Ykhlef.', 'التشكيلة الأساسية للنادي الرياضي القسنطيني أمام شبيبة الساورة:\nملالة (حارس) – مداحي (قائد)، شيخي، زغاد، أتيبو، بيزيمانا، بركان، بكير، لحمري، لغول، إيفرا.\nالاحتياط: نصير، بن موسى، بلقوراي، عيون، روجرز، شعبان، جاوشي، شكال، يخلف.', '#TheDean1898 #StartingXI', '', '', '', '', 1),
(21, 12, NULL, 'images/Actualite/communique-staff-technique.jpg', '📢 Communiqué', '📢 بيان رسمي', 'Communiqué officiel : Marouani Amara entraîneur, Dr Kacemi Abdelmalek directeur technique sportif', 'بيان رسمي: تعيين مرواني عمارة مدرباً للفريق الأول والدكتور قاسمي عبد المالك مديراً تقنياً رياضياً', 'La direction du CSC nomme M. Marouani Amara entraîneur de l\'équipe première et le Pr Dr Kacemi Abdelmalek directeur technique sportif du club.', 'إدارة النادي الرياضي القسنطيني تعين السيد مرواني عمارة مدرباً للفريق الأول والأستاذ الدكتور قاسمي عبد المالك مديراً تقنياً رياضياً للنادي.', 'Dans le cadre des efforts de la direction du CS Constantine visant à renforcer ses structures techniques et organisationnelles et à doter le staff de l\'équipe première des compétences nécessaires, et après la réunion de la commission chargée d\'étudier et d\'évaluer les dossiers des candidats, il a été décidé ce qui suit :\n• Nomination de M. Marouani Amara au poste d\'entraîneur de l\'équipe première (seniors), accompagné de son staff technique.\n• Nomination du Pr Dr Kacemi Abdelmalek au poste de directeur technique sportif du club.\nCes nominations s\'inscrivent dans la vision de la direction d\'instaurer une organisation technique et administrative plus efficace et de renforcer la coordination entre les différentes composantes du club, afin de garantir de bonnes conditions de travail, d\'atteindre les objectifs sportifs fixés et d\'améliorer le niveau des performances et des résultats, conformément aux ambitions du club et aux attentes de ses fidèles supporters.\nÀ cette occasion, la direction du club adresse ses félicitations aux personnes concernées pour cette confiance et leur souhaite plein succès dans leurs nouvelles missions. Elle souligne l\'importance de l\'union des efforts, de l\'esprit de responsabilité et du travail collectif, au service des couleurs du club et pour défendre son histoire et son rang.\nLa direction réaffirme également son engagement à continuer à travailler pour mettre l\'équipe dans les meilleures conditions possibles, afin qu\'elle réponde aux attentes de ses supporters, qui ont été et resteront le véritable soutien du CS Constantine.\nPlein succès à notre club, et encore plus de brillance et de victoires.\n« Ensemble pour le CS Constantine » — La direction du CS Constantine', 'في إطار مساعي إدارة النادي الرياضي القسنطيني الرامية إلى تعزيز هياكله الفنية والتنظيمية، وتدعيم الطاقم المشرف على الفريق الأول بالكفاءات اللازمة، وبعد اجتماع اللجنة المكلّفة بدراسة ملفات المترشحين وتقييمها، تقرّر ما يلي:\n• تعيين السيد مرواني عمارة مدرباً للفريق الأول (الأكابر)، بمرافقة طاقمه الفني.\n• تعيين الأستاذ الدكتور قاسمي عبد المالك مديراً تقنياً رياضياً للنادي.\nوتأتي هذه التعيينات في سياق رؤية الإدارة الرامية إلى إرساء تنظيم فني وإداري أكثر فعالية، وتعزيز التنسيق بين مختلف مكونات النادي، بما يضمن توفير الظروف الملائمة للعمل وتحقيق الأهداف الرياضية المسطّرة، والارتقاء بمستوى الأداء والنتائج بما يتماشى مع طموحات النادي وتطلعات جماهيره الوفية.\nوبهذه المناسبة، تتقدم إدارة النادي بتهانيها إلى جميع المعنيين بهذه الثقة، متمنية لهم كامل التوفيق والنجاح في أداء مهامهم الجديدة، ومؤكدة في الوقت ذاته على أهمية تضافر الجهود وروح المسؤولية والعمل الجماعي، خدمةً لألوان النادي ودفاعاً عن تاريخه العريق ومكانته الرياضية.\nكما تجدد إدارة النادي التزامها بمواصلة العمل من أجل وضع الفريق في أفضل الظروف الممكنة، بما يسمح له بتحقيق تطلعات أنصاره وإسعاد جماهيره التي كانت وستظل السند الحقيقي والداعم الأول للنادي الرياضي القسنطيني.\nكل التوفيق والنجاح لنادينا، ومزيداً من التألق والانتصارات.\n"معاً من أجل النادي الرياضي القسنطيني" — إدارة النادي الرياضي القسنطيني', '#TheDean1898 #CSC', '', '', '', '', 1),
(19, 11, '2026-10-10', 'images/Actualite/ultras-visite-2.jpg', '💚 Supporters', '💚 الأنصار', 'Les Ultras Green Army présents à la reprise', 'حضور مميز لمجموعة "Ultras Green Army" في حصة الاستئناف', 'Le groupe de supporters « Ultras Green Army » s\'est rendu à la séance de reprise pour soutenir les joueurs et leur remonter le moral.', 'تنقلت مجموعة الأنصار "Ultras Green Army" إلى حصة الاستئناف من أجل مساندة اللاعبين ورفع معنوياتهم.', 'La séance de reprise a été marquée par la présence remarquée du groupe de supporters « Ultras Green Army », venu à l\'entraînement pour soutenir les joueurs et leur remonter le moral. Les supporters les ont encouragés à redoubler d\'efforts et à travailler avec sérieux afin de continuer à honorer les couleurs du club et à répondre aux attentes des supporters.\nCette présence a eu un effet positif sur les joueurs, qui ont apprécié cette initiative et ont affirmé leur détermination à redoubler d\'efforts et à donner le meilleur d\'eux-mêmes pour obtenir de bons résultats lors des prochaines échéances.\nLes membres du groupe ont créé une superbe ambiance pendant la séance, avec des chants à la gloire du club, des scènes qui montrent leur attachement et leur fidélité au Doyen, et qui confirment une fois de plus que la relation entre l\'équipe et ses supporters repose sur un soutien constant, en toutes circonstances.\nVive le Doyen dans le cœur de ses supporters !', 'شهدت حصة الاستئناف حضورا مميزا لمجموعة الأنصار "Ultras Green Army" التي تنقلت إلى التدريبات من أجل مساندة اللاعبين ورفع معنوياتهم، حيث حثوهم على بذل المزيد من الجهود والعمل بكل جدية من أجل مواصلة تشريف ألوان الفريق وتحقيق تطلعات الأنصار.\nهذا وقد كان للحضور الأثر الإيجابي في نفوس اللاعبين، الذين استحسنوا هذه المبادرة التشجيعية، مؤكدين عزمهم على مضاعفة المجهودات وتقديم أفضل المستويات لتحقيق نتائج إيجابية في قادم المواعيد.\nيذكر أن أعضاء المجموعة صنعوا أجواء رائعة في الحصة التدريبية، من خلال الأهازيج والتغني بألوان الفريق، في مشاهد تؤكد مدى تعلقهم بناديهم ووفاءهم له، وتؤكد مرة أخرى أن العلاقة بين الفريق وجماهيره تظل قائمة على الدعم المتواصل والوقوف إلى جانبه في مختلف الظروف.\nعاش العميد بقلوب محبيه', '#TheDean1898 #UltrasGreenArmy', 'images/Actualite/ultras-visite-2.jpg\nimages/Actualite/ultras-visite-1.jpg', '', '', '', 1),
(20, 10, '2026-10-10', 'images/Actualite/reprise-entrainement-1.jpg', '🏃 Entraînement', '🏃 تدريبات', 'Retour à l\'entraînement après un jour de repos', 'العودة إلى التدريبات بعد يوم راحة', 'Après une journée de repos, l\'équipe a repris l\'entraînement avec une séance en soirée.', 'بعد يوم من الراحة، عاد الفريق إلى التدريبات بحصة مسائية.', 'Après une journée de repos, les joueurs du CS Constantine ont repris le chemin de l\'entraînement avec une séance en soirée, sous la conduite du staff technique.\nLe groupe poursuit sa préparation en vue du déplacement à Khenchela, lundi 12 octobre 2026 à 15h00, pour le compte de la 5e journée de la Ligue 1 Mobilis.', 'بعد يوم من الراحة، عاد لاعبو النادي الرياضي القسنطيني إلى التدريبات بحصة مسائية تحت إشراف الطاقم الفني.\nويواصل الفريق تحضيراته تحسبا للتنقل إلى خنشلة يوم الإثنين 12 أكتوبر 2026 على الساعة 15:00، لحساب الجولة الخامسة من الرابطة المحترفة الأولى موبيليس.', '#TheDean1898 #DimaCsc', 'images/Actualite/reprise-entrainement-1.jpg\nimages/Actualite/reprise-entrainement-2.jpg\nimages/Actualite/reprise-entrainement-3.jpg\nimages/Actualite/reprise-entrainement-4.jpg\nimages/Actualite/reprise-entrainement-5.jpg\nimages/Actualite/reprise-entrainement-6.jpg', '', '', '', 1),
(15, 9, '2026-10-07', 'images/Actualite/ft-csc-usb-4-0-final.jpg', '⚽ Résultat', '⚽ نتيجة', 'Full time : CSC 4 – 0 US Biskra', 'نهاية المباراة: شباب قسنطينة 4 – 0 إتحاد بسكرة', 'Large victoire du Doyen face à l\'US Biskra (4-0) au stade Chahid Hamlaoui, pour le compte de la 4e journée de la Ligue 1 Mobilis.', 'فوز عريض للعميد على إتحاد بسكرة (4-0) بملعب الشهيد حملاوي، لحساب الجولة الرابعة من الرابطة المحترفة الأولى موبيليس.', 'Le CS Constantine s\'est largement imposé face à l\'US Biskra (4-0) ce mercredi 7 octobre 2026 au stade Chahid Hamlaoui, pour le compte de la 4e journée de la Ligue 1 Mobilis.\nButs : Evra (37\'), contre son camp (51\'), Rebiai (55\'), Djaouchi (72\').\nAvec cette victoire, le Doyen remonte à la 2e place du classement avec 7 points.', 'حقق النادي الرياضي القسنطيني فوزاً عريضاً على إتحاد بسكرة (4-0) هذا الأربعاء 7 أكتوبر 2026 بملعب الشهيد حملاوي، لحساب الجولة الرابعة من الرابطة المحترفة الأولى موبيليس.\nالأهداف: إيفرا (37\')، ضد مرماه (51\')، ربيعي (55\')، جاوشي (72\').\nبهذا الفوز يرتقي العميد إلى المركز الثاني في الترتيب برصيد 7 نقاط.', '#TheDean1898 #CSCUSB #DimaCsc', '', '', '', '', 1),
(18, 8, '2026-10-09', 'images/Actualite/fixtures-octobre.jpg', '📅 Calendrier', '📅 الرزنامة', 'Les matchs du CSC en octobre', 'مباريات العميد في شهر أكتوبر', 'Le programme du Doyen en octobre : US Biskra, USM Khenchela, JS El Biar et Olympique Akbou.', 'برنامج العميد في شهر أكتوبر: إتحاد بسكرة، إتحاد خنشلة، شبيبة الأبيار وأولمبيك أقبو.', 'Voici le programme du CS Constantine pour le mois d\'octobre en Ligue 1 Mobilis :\n• Mercredi 7 octobre, 18h00 : CSC – US Biskra (stade Chahid Hamlaoui) — victoire 4-0\n• Lundi 12 octobre, 15h00 : USM Khenchela – CSC (stade Amar Hamam, Khenchela)\n• Samedi 17 octobre, 17h00 : CSC – JS El Biar (stade Chahid Hamlaoui)\n• Vendredi 23 octobre, 15h15 : Olympique Akbou – CSC (stade des Chouhada, Akbou)', 'إليكم برنامج النادي الرياضي القسنطيني لشهر أكتوبر في الرابطة المحترفة الأولى موبيليس:\n• الأربعاء 7 أكتوبر، 18:00: شباب قسنطينة – إتحاد بسكرة (ملعب الشهيد حملاوي) — فوز 4-0\n• الإثنين 12 أكتوبر، 15:00: إتحاد خنشلة – شباب قسنطينة (ملعب عمار حمام، خنشلة)\n• السبت 17 أكتوبر، 17:00: شباب قسنطينة – شبيبة الأبيار (ملعب الشهيد حملاوي)\n• الجمعة 23 أكتوبر، 15:15: أولمبيك أقبو – شباب قسنطينة (ملعب الشهداء، أقبو)', '#TheDean1898 #FixturesOctober', '', '', '', '', 1),
(14, 7, '2026-10-06', 'images/Actualite/ticket-csc-usb.jpg', '🎫 Billetterie', '🎫 التذاكر', 'Billetterie : CSC – US Biskra', 'التذاكر: شباب قسنطينة – إتحاد بسكرة', 'La plateforme numérique « Tadkirati » est ouverte : achetez vos billets pour CSC – US Biskra, mercredi 7 octobre 2026 à 18h00 au stade Chahid Hamlaoui.', 'تم فتح المنصة الرقمية "تذكرتي": اقتنوا تذاكركم لمباراة العميد ضد إتحاد بسكرة، الأربعاء 07 أكتوبر 2026 على الساعة 18:00 بملعب الشهيد حملاوي.', 'La direction du CS Constantine informe ses fidèles supporters souhaitant assister au match du Doyen face à l\'US Biskra, comptant pour la 4e journée de la Ligue 1 Mobilis, prévu ce mercredi 7 octobre 2026 à 18h00 au stade Chahid Hamlaoui de Constantine, que la plateforme numérique « Tadkirati » est ouverte.\nVous pouvez dès maintenant acheter vos billets en ligne.', 'تعلم إدارة النادي الرياضي القسنطيني أنصار الفريق الأوفياء الراغبين بمشاهدة مباراة العميد ضد إتحاد بسكرة في إطار الجولة 04 من الرابطة المحترفة الأولى المقررة هذا الأربعاء 07 أكتوبر 2026 بداية من الساعة 18:00 بملعب الشهيد حملاوي بقسنطينة، أنه قد تم فتح المنصة الرقمية "تذكرتي".\nوبإمكانكم الآن اقتناء تذاكركم عبر الرابط.', '#TheDean1898 #CSCUSB', '', '', '', '', 1),
(13, 6, '2026-10-05', 'images/Actualite/next-csc-usb.jpg', '📅 Next match', '📅 المباراة القادمة', 'Next match : CSC – US Biskra', 'المباراة القادمة: شباب قسنطينة – إتحاد بسكرة', '4e journée : CSC – US Biskra, mercredi 7 octobre 2026 à 18h00 au stade Chahid Hamlaoui.', 'الجولة 4: شباب قسنطينة – إتحاد بسكرة، الأربعاء 7 أكتوبر 2026 على الساعة 18:00 بملعب الشهيد حملاوي.', '', '', '#TheDean1898 #CSCUSB', '', '', '', '', 1),
(10, 5, '2026-09-19', 'https://lfp.dz/medias/ar-6ab8287a7418f.jpg', '⚽ Résultat', '⚽ نتيجة', 'ES Sétif 5 – 1 CSC', 'وفاق سطيف 5 – 1 شباب قسنطينة', 'Défaite du Doyen à Sétif lors de la 3e journée de la Ligue 1 Mobilis.', 'خسارة العميد في سطيف خلال الجولة الثالثة من الرابطة المحترفة الأولى موبيليس.', 'Le CS Constantine s\'est incliné face à l\'ES Sétif (5-1) le samedi 19 septembre 2026, pour le compte de la 3e journée de la Ligue 1 Mobilis.', 'انهزم النادي الرياضي القسنطيني أمام وفاق سطيف (5-1) يوم السبت 19 سبتمبر 2026، لحساب الجولة الثالثة من الرابطة المحترفة الأولى موبيليس.', '#TheDean1898 #ESSCSC', '', '', '', '', 1),
(9, 4, '2026-09-12', '', '⚽ Résultat', '⚽ نتيجة', 'CSC 3 – 0 ASO Chlef', 'شباب قسنطينة 3 – 0 جمعية الشلف', 'Première victoire de la saison pour le Doyen, large vainqueur de l\'ASO Chlef lors de la 2e journée.', 'أول فوز للعميد هذا الموسم، بانتصار عريض على جمعية الشلف خلال الجولة الثانية.', 'Le CS Constantine s\'est imposé 3-0 face à l\'ASO Chlef le samedi 12 septembre 2026, pour le compte de la 2e journée de la Ligue 1 Mobilis. Il s\'agit de la première victoire du club cette saison.', 'فاز النادي الرياضي القسنطيني على جمعية الشلف بثلاثية نظيفة (3-0) يوم السبت 12 سبتمبر 2026، لحساب الجولة الثانية من الرابطة المحترفة الأولى موبيليس، في أول انتصار للنادي هذا الموسم.', '#TheDean1898 #CSCASO', '', '', '', '', 1),
(8, 3, '2026-09-05', '', '⚽ Résultat', '⚽ نتيجة', 'CR Témouchent 1 – 1 CSC', 'شباب تموشنت 1 – 1 شباب قسنطينة', 'Le Doyen ramène le point du match nul de Témouchent pour l\'ouverture de la saison 2026/2027.', 'العميد يعود بنقطة التعادل من تموشنت في افتتاح موسم 2026/2027.', 'Pour la 1re journée de la Ligue 1 Mobilis 2026/2027, le CS Constantine a fait match nul (1-1) sur le terrain du CR Témouchent, le samedi 5 septembre 2026.', 'في الجولة الأولى من الرابطة المحترفة الأولى موبيليس 2026/2027، تعادل النادي الرياضي القسنطيني (1-1) أمام شباب تموشنت خارج الديار، يوم السبت 5 سبتمبر 2026.', '#TheDean1898 #CRTCSC', '', '', '', '', 1),
(1, 2, NULL, 'images/Actualite/Ooredoonews.jpeg', '🤝 Partenariat officiel', '🤝 شراكة رسمية', '🤝 Officiel : Ooredoo, nouveau sponsor 🟢🖤', '🤝 رسمياً: أوريدو ممول جديد 🟢🖤', 'La direction du CS Constantine annonce la signature d\'un contrat de sponsoring de deux ans avec Ooredoo.', 'تعلن إدارة النادي الرياضي القسنطيني عن إبرام عقد رعاية مع شركة أوريدو لمدة سنتين.', '', '', '#TheDean1898 #Ooredoo', '', '', '', '', 1),
(2, 1, NULL, 'images/Actualite/news7.jpg', 'Site officiel', 'الموقع الرسمي', 'Le Doyen renforce sa présence numérique 🟢⚫🌐', '"العميد" يعزز ريادته الرقمية 🟢⚫🌐', 'Nous avons le plaisir d\'annoncer le lancement du site internet officiel du Club Sportif Constantinois.', 'يسعدنا إعلان إطلاق الموقع الإلكتروني الرسمي للنادي الرياضي القسنطيني.', '', '', '#TheDean1898 #DimaCsc', '', '', '', '', 1);
